package com.cafeina.executor;
import static org.junit.Assert.*; import java.util.*; import org.junit.Test;
public final class JournaledAiMissionToolRunnerTest {
 private AiTool tool(String n,boolean success){return new AiTool(){public String name(){return n;}public Set<String> requiredCapabilities(){return Collections.singleton("run");}public AiToolResult execute(AiToolRequest r){return success?AiToolResult.success(n):AiToolResult.failure(n);}};}
 @Test public void journalsOrderedExecutionAndStopsAtFailure(){InMemoryAiMissionStore s=new InMemoryAiMissionStore();s.save(new AiMissionRecord("m","p","g",AiMissionState.RUNNING,1));AiToolRegistry reg=new AiToolRegistry();reg.register(tool("a",true));reg.register(tool("b",false));reg.register(tool("c",true));AiToolExecutionJournal j=new AiToolExecutionJournal();JournaledAiMissionToolRunner r=new JournaledAiMissionToolRunner(s,new AiToolExecutor(reg,new AiCapabilitySet(Collections.singleton("run"))),new AiToolExecutionPolicy(5),j);AiToolRequest q=new AiToolRequest("p",null);r.run("m",new AiToolPlan(Arrays.asList(new AiToolPlan.Step("a",q),new AiToolPlan.Step("b",q),new AiToolPlan.Step("c",q))),10);assertEquals(2,j.forMission("m").size());assertEquals("a",j.forMission("m").get(0).toolName);assertFalse(j.forMission("m").get(1).success);}
 @Test public void deniedCapabilityProducesNoExecutionRecord(){InMemoryAiMissionStore s=new InMemoryAiMissionStore();s.save(new AiMissionRecord("m","p","g",AiMissionState.RUNNING,1));AiToolRegistry reg=new AiToolRegistry();reg.register(tool("a",true));AiToolExecutionJournal j=new AiToolExecutionJournal();JournaledAiMissionToolRunner r=new JournaledAiMissionToolRunner(s,new AiToolExecutor(reg,AiCapabilitySet.none()),new AiToolExecutionPolicy(5),j);AiToolRequest q=new AiToolRequest("p",null);assertThrows(SecurityException.class,()->r.run("m",new AiToolPlan(Collections.singletonList(new AiToolPlan.Step("a",q))),10));assertTrue(j.forMission("m").isEmpty());}
}
